-- Executable regression assertions. Isolated SAMPLE tenants and identities always roll back.
begin;
select set_config('app.sample_operator_id',gen_random_uuid()::text,true);
select set_config('app.sample_reviewer_id',gen_random_uuid()::text,true);
select set_config('app.sample_outsider_id',gen_random_uuid()::text,true);
select set_config('app.sample_company_id',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select current_setting(setting)::uuid,'authenticated','authenticated','sample+'||current_setting(setting)||'@invalid.test',now(),'{"provider":"email","providers":["email"]}'::jsonb,'{"display_name":"SAMPLE Operator"}'::jsonb,now(),now()
from unnest(array['app.sample_operator_id','app.sample_reviewer_id','app.sample_outsider_id']) setting;
insert into public.companies(id,name,created_by) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Procurement Test',current_setting('app.sample_operator_id')::uuid);
insert into public.plants(company_id,name) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Plant');
insert into public.company_memberships(company_id,user_id)
select current_setting('app.sample_company_id')::uuid,current_setting(setting)::uuid from unnest(array['app.sample_operator_id','app.sample_reviewer_id']) setting;
insert into public.user_company_roles(company_id,user_id,role)
select current_setting('app.sample_company_id')::uuid,current_setting(setting)::uuid,'admin' from unnest(array['app.sample_operator_id','app.sample_reviewer_id']) setting;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('app.sample_operator_id'),true);
select set_config('request.jwt.claim.role','authenticated',true);

do $$
declare
 c uuid:=current_setting('app.sample_company_id')::uuid; actor uuid:=current_setting('app.sample_operator_id')::uuid;
 raw_item uuid; out_item uuid; customer uuid; loc uuid; wh uuid; centre uuid; pkg uuid; rfq uuid; quote uuid; so uuid; line uuid;
 wo uuid; job1 uuid; job2 uuid; lot uuid; issue uuid; issue2 uuid; raw_plan uuid; final_plan uuid; result_id uuid; output_id uuid; output_lot uuid;
 inspect_id uuid; ncr uuid; reservation uuid; shipment uuid; revision_value integer; j jsonb; payload jsonb;
 topup_lot uuid; external_lot uuid; replacement_wo uuid; zero_wo uuid; zero_job1 uuid; zero_job2 uuid; zero_issue uuid;
 vendor_supplier uuid;vendor_order uuid;vendor_event uuid;vendor_return uuid;
 derived_lot uuid; merged_lot uuid; derived_ncr uuid; derived_reservation uuid;
 rework_pkg uuid; rework_wo uuid; rework_job uuid; rework_issue uuid; rework_output uuid; rework_lot uuid;
begin
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-RAW','SAMPLE wire','kg') returning id into raw_item;
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-FG','SAMPLE fastener','pcs') returning id into out_item;
 insert into public.customers(company_id,code,name) values(c,'SAMPLE-C','SAMPLE Customer') returning id into customer;
 insert into public.warehouses(company_id,plant_id,code,name) select c,id,'SAMPLE-W','SAMPLE Warehouse' from public.plants where company_id=c returning id into wh;
 insert into public.stock_locations(company_id,warehouse_id,code,name) values(c,wh,'SAMPLE-L','SAMPLE Location') returning id into loc;
 insert into public.work_centres(company_id,plant_id,code,name) select c,id,'SAMPLE-WC','SAMPLE Centre' from public.plants where company_id=c returning id into centre;
 payload:=jsonb_build_object('item_id',out_item,'revision_label','A','basis_quantity','1','components',jsonb_build_array(jsonb_build_object('item_id',raw_item,'quantity','0.1','uom','kg','scrap_allowance_pct','0')),'operations',jsonb_build_array(jsonb_build_object('sequence',10,'work_centre_id',centre,'name','SAMPLE Form'),jsonb_build_object('sequence',20,'work_centre_id',centre,'name','SAMPLE Finish')));
 begin perform public.production_command(c,'create_package',jsonb_set(payload,'{components,0,scrap_allowance_pct}','"0.00001"'::jsonb),'pct-precision'); raise exception 'SAMPLE_SCRAP_ALLOWANCE_ROUNDED'; exception when others then if sqlerrm<>'INVALID_SCRAP_ALLOWANCE' then raise; end if;end;
 pkg:=public.production_command(c,'create_package',payload,'pkg');
 if public.production_command(c,'create_package',payload,'pkg')<>pkg then raise exception 'SAMPLE_PACKAGE_RETRY_CHANGED'; end if;
 begin perform public.production_command(c,'create_package',payload||'{"revision_label":"B"}','pkg'); raise exception 'SAMPLE_CHANGED_RETRY_ALLOWED'; exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise; end if; end;
 perform public.production_command(c,'approve_package',jsonb_build_object('package_id',pkg),'approve-pkg');
 begin
  insert into public.bom_lines(company_id,bom_revision_id,component_item_id,quantity,uom)
   select c,bom_revision_id,out_item,1,'pcs' from public.engineering_packages where id=pkg;
  raise exception 'SAMPLE_APPROVED_BOM_INSERT_ALLOWED';
 exception when others then if sqlerrm<>'APPROVED_REVISION_IMMUTABLE' then raise; end if; end;
 begin update public.items set base_uom='m' where id=raw_item; raise exception 'SAMPLE_APPROVED_BOM_UOM_DRIFT'; exception when others then if sqlerrm<>'UOM_IN_USE' then raise; end if; end;
 rfq:=public.create_rfq(c,'SAMPLE-R',customer,'SAMPLE request',jsonb_build_array(jsonb_build_object('item_id',out_item,'requested_description','SAMPLE fastener','quantity','10','uom','pcs','required_by',null)),'rfq');
 perform public.record_feasibility(c,rfq,'feasible',null,(select bom_revision_id from public.engineering_packages where id=pkg),(select routing_revision_id from public.engineering_packages where id=pkg),'SAMPLE',1,'feas');
 quote:=public.create_quotation(c,rfq,'SAMPLE-Q','INR',current_date+30,jsonb_build_array(jsonb_build_object('item_id',out_item,'quantity','10','uom','pcs','unit_price','1')),'quote');
 perform public.approve_quotation(c,quote,1,'quote-approve');
 so:=public.accept_quotation_create_sales_order(c,quote,'SAMPLE-SO','SAMPLE-PO',current_date+10,2,'accept');
 select id into line from public.sales_order_lines where sales_order_id=so;
 wo:=public.production_command(c,'create_work_order',jsonb_build_object('sales_order_line_id',line,'package_id',pkg,'number','SAMPLE-WO','quantity','6','start_date',current_date,'due_date',current_date+7),'work');
 begin perform public.production_command(c,'create_work_order',jsonb_build_object('sales_order_line_id',line,'package_id',pkg,'number','SAMPLE-WO-OVER','quantity','5','start_date',current_date,'due_date',current_date+7),'over-work'); raise exception 'SAMPLE_OVERPLAN_ALLOWED'; exception when others then if sqlerrm<>'ORDER_QUANTITY_EXCEEDED' then raise; end if; end;
 if (public.get_factory_report(c,'shortages')->'rows'->0->>'quantity')::numeric is distinct from 0.6 then raise exception 'SAMPLE_REPORT_SHORTAGE_QUANTITY';end if;
 begin perform public.production_command(c,'release_work_order',jsonb_build_object('work_order_id',wo,'revision',1),'short'); raise exception 'SAMPLE_SHORTAGE_RELEASED'; exception when others then if sqlerrm<>'MATERIAL_SHORTAGE' then raise; end if; end;
 raw_plan:=public.quality_command(c,'create_plan',jsonb_build_object('item_id',raw_item,'label','SAMPLE Incoming','version','A','sample_size',1,'characteristics','[{"key":"condition","label":"SAMPLE condition","type":"attribute","expected":"PASS"}]'::jsonb),'raw-plan');
 perform public.quality_command(c,'approve_plan',jsonb_build_object('plan_id',raw_plan),'raw-plan-ok');
 final_plan:=public.quality_command(c,'create_plan',jsonb_build_object('item_id',out_item,'label','SAMPLE Final','version','A','sample_size',2,'characteristics','[{"key":"dimension","label":"SAMPLE diameter","type":"numeric","uom":"mm","min":"7.9","max":"8.1"}]'::jsonb),'final-plan');
 perform public.quality_command(c,'approve_plan',jsonb_build_object('plan_id',final_plan),'final-plan-ok');
 -- Adding quantity to an already-inspected held lot invalidates that inspection.
 topup_lot:=public.receive_finished_goods(c,raw_item,loc,'SAMPLE-TOPUP',1,'kg','topup-receive');
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',raw_plan,'lot_id',topup_lot,'kind','incoming','revision',1,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE before top-up'),'inspect-topup');
 perform public.receive_finished_goods(c,raw_item,loc,'SAMPLE-TOPUP',0.1,'kg','topup-add');
 if (select revision from public.stock_lots where id=topup_lot)<>2 then raise exception 'SAMPLE_TOPUP_REVISION_UNCHANGED'; end if;
 begin perform public.release_stock_lot(c,topup_lot,2,'topup-stale-release'); raise exception 'SAMPLE_TOPUP_STALE_INSPECTION_RELEASED'; exception when others then if sqlerrm<>'INSPECTION_REQUIRED' then raise; end if; end;
 -- Independent stock cannot be allocated over an already committed production plan.
 external_lot:=public.receive_finished_goods(c,out_item,loc,'SAMPLE-EXTERNAL',10,'pcs','external-receive');
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',final_plan,'lot_id',external_lot,'kind','incoming','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8","8"]}]'::jsonb,'reason','SAMPLE external stock'),'inspect-external');
 perform public.release_stock_lot(c,external_lot,1,'release-external');
 begin perform public.reserve_finished_goods(c,line,external_lot,5,(select revision from public.sales_orders where id=so),'external-overcommit'); raise exception 'SAMPLE_EXTERNAL_RESERVATION_OVERPLAN'; exception when others then if sqlerrm<>'ORDER_QUANTITY_EXCEEDED' then raise; end if; end;
 lot:=public.receive_finished_goods(c,raw_item,loc,'SAMPLE-RAW-LOT',3,'kg','raw-receive');
 begin perform public.release_stock_lot(c,lot,1,'bypass'); raise exception 'SAMPLE_INSPECTION_BYPASS'; exception when others then if sqlerrm<>'INSPECTION_REQUIRED' then raise; end if; end;
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',raw_plan,'lot_id',lot,'job_card_id',null,'kind','incoming','revision',1,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE inspected','supersedes_id',null),'inspect-raw');
 perform public.release_stock_lot(c,lot,1,'release-raw');
 perform public.production_command(c,'release_work_order',jsonb_build_object('work_order_id',wo,'revision',1),'release-wo');
 select id into job1 from public.job_cards where work_order_id=wo and sequence=10;
 select id into job2 from public.job_cards where work_order_id=wo and sequence=20;
 begin perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job2,'revision',1),'out-order'); raise exception 'SAMPLE_PREDECESSOR_BYPASS'; exception when others then if sqlerrm<>'PREDECESSOR_PENDING' then raise; end if; end;
 issue:=public.production_command(c,'issue_material',jsonb_build_object('work_order_id',wo,'job_card_id',job1,'lot_id',lot,'quantity','0.6','uom','kg','lot_revision',2),'issue');
 if (public.get_factory_report(c,'wip')->'rows'->0->>'quantity')::numeric is distinct from 0.6 then raise exception 'SAMPLE_REPORT_WIP_QUANTITY';end if;
 if not exists(select 1 from public.production_material_positions where work_order_id=wo and wip_quantity=0.6 and consumed_quantity=0) then raise exception 'SAMPLE_WIP_NOT_DERIVED'; end if;
 begin perform public.production_command(c,'issue_material',jsonb_build_object('work_order_id',wo,'job_card_id',job1,'lot_id',lot,'quantity','1','uom','kg','lot_revision',3),'excess-issue'); raise exception 'SAMPLE_OVERISSUE_ALLOWED'; exception when others then if sqlerrm<>'MATERIAL_REQUIREMENT_EXCEEDED' then raise; end if; end;
 perform public.production_command(c,'return_material',jsonb_build_object('issue_id',issue,'quantity','0.1','reason','SAMPLE unused','lot_revision',3),'return');
 if not exists(select 1 from public.stock_lots where id=lot and qc_status='hold') then raise exception 'SAMPLE_RETURN_QC_BYPASS'; end if;
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',raw_plan,'lot_id',lot,'job_card_id',null,'kind','incoming','revision',4,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE reinspected'),'inspect-return');
 perform public.release_stock_lot(c,lot,4,'release-return');
 issue2:=public.production_command(c,'issue_material',jsonb_build_object('work_order_id',wo,'job_card_id',job1,'lot_id',lot,'quantity','0.1','uom','kg','lot_revision',5),'issue2');
 perform public.production_command(c,'consume_material',jsonb_build_object('issue_id',issue,'quantity','0.5','reason','SAMPLE used'),'consume');
 perform public.production_command(c,'consume_material',jsonb_build_object('issue_id',issue2,'quantity','0.1','reason','SAMPLE used'),'consume2');
 perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job1,'revision',1),'start1');
 perform public.production_command(c,'complete_job',jsonb_build_object('job_card_id',job1,'revision',2,'good_quantity','3','scrap_quantity','0','reason','SAMPLE partial'),'partial1');
 if not exists(select 1 from public.job_cards where id=job1 and status='in_progress' and scrap_quantity=0) then raise exception 'SAMPLE_PENDING_BECAME_SCRAP'; end if;
 perform public.production_command(c,'complete_job',jsonb_build_object('job_card_id',job1,'revision',3,'good_quantity','2','scrap_quantity','1','reason','SAMPLE remaining'),'finish1');
 perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job2,'revision',1),'start2');
 if not exists(select 1 from public.job_cards where id=job2 and planned_quantity=5) then raise exception 'SAMPLE_PROCESS_LOSS_NOT_PROPAGATED'; end if;
 perform public.production_command(c,'complete_job',jsonb_build_object('job_card_id',job2,'revision',2,'good_quantity','5','scrap_quantity','0','reason','SAMPLE finish'),'finish2');
 output_id:=public.production_command(c,'record_output',jsonb_build_object('work_order_id',wo,'location_id',loc,'lot_code','SAMPLE-OUTPUT','quantity','5','uom','pcs'),'output');
 select lot_id into output_lot from public.production_outputs where id=output_id;
 if not exists(select 1 from public.lot_genealogy where parent_lot_id=lot and child_lot_id=output_lot and work_order_id=wo) then raise exception 'SAMPLE_GENEALOGY_MISSING'; end if;
 begin perform public.production_command(c,'close_work_order',jsonb_build_object('work_order_id',wo,'revision',(select revision from public.work_orders where id=wo)),'close-held'); raise exception 'SAMPLE_CLOSE_QC_BYPASS'; exception when others then if sqlerrm<>'QUALITY_PENDING' then raise; end if; end;
 begin perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',final_plan,'lot_id',output_lot,'job_card_id',null,'kind','final','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8"]}]'::jsonb,'reason','SAMPLE incomplete'),'bad-samples'); raise exception 'SAMPLE_MISSING_SAMPLES_ALLOWED'; exception when others then if sqlerrm<>'SAMPLE_COUNT_MISMATCH' then raise; end if; end;
 inspect_id:=public.quality_command(c,'inspect',jsonb_build_object('plan_id',final_plan,'lot_id',output_lot,'job_card_id',null,'kind','final','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8.2","8"]}]'::jsonb,'reason','SAMPLE failed'),'failed-inspect');
 if not exists(select 1 from public.inspections where id=inspect_id and result='failed') then raise exception 'SAMPLE_OUT_OF_RANGE_PASSED'; end if;
 begin perform public.release_stock_lot(c,output_lot,1,'release-failed'); raise exception 'SAMPLE_FAILED_RELEASED'; exception when others then if sqlerrm<>'INSPECTION_REQUIRED' then raise; end if; end;
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',final_plan,'lot_id',output_lot,'job_card_id',null,'kind','final','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8","8.01"]}]'::jsonb,'reason','SAMPLE correction','supersedes_id',inspect_id),'pass-inspect');
 if (select count(*) from public.inspections where lot_id=output_lot)<>2 then raise exception 'SAMPLE_INSPECTION_OVERWRITTEN'; end if;
 perform public.release_stock_lot(c,output_lot,1,'release-output');
 -- External processing retains production pins, explicit loss and final-QC/close gates.
 begin
  insert into public.suppliers(company_id,code,name) values(c,'SAMPLE-PROCESSOR','SAMPLE processor') returning id into vendor_supplier;
  vendor_order:=public.vendor_jobwork_command(c,'create',jsonb_build_object('lot_id',output_lot,'supplier_id',vendor_supplier,'number','SAMPLE-VENDOR-WORK','process','SAMPLE finish','due_date',current_date+7,'quantity','2','uom','pcs'),'vendor-create');
  perform public.vendor_jobwork_command(c,'send',jsonb_build_object('order_id',vendor_order,'revision',1,'lot_revision',2,'quantity','2','uom','pcs','reference','SAMPLE outward','reason','SAMPLE external custody'),'vendor-send');
  begin perform public.production_command(c,'close_work_order',jsonb_build_object('work_order_id',wo,'revision',(select revision from public.work_orders where id=wo)),'vendor-close-before-return');raise exception 'SAMPLE_VENDOR_CLOSURE_BYPASS';exception when others then if sqlerrm<>'VENDOR_CUSTODY_PENDING' then raise;end if;end;
  vendor_event:=public.vendor_jobwork_command(c,'receive',jsonb_build_object('order_id',vendor_order,'revision',2,'quantity','1','uom','pcs','reference','SAMPLE inward','reason','SAMPLE partial return','location_id',loc,'lot_code','SAMPLE-PROCESSOR-RETURN'),'vendor-receive');
  select output_lot_id into vendor_return from public.vendor_custody_events where id=vendor_event;
  perform public.vendor_jobwork_command(c,'loss',jsonb_build_object('order_id',vendor_order,'revision',3,'quantity','1','uom','pcs','reference','SAMPLE verified loss','reason','SAMPLE shortage reviewed'),'vendor-loss');
  if not exists(select 1 from public.lot_trace_context where lot_id=vendor_return and requires_final and sales_order_line_id=line and work_order_ids=array[wo]) then raise exception 'SAMPLE_VENDOR_PRODUCTION_CONTEXT_LOST';end if;
  if not exists(select 1 from public.production_demand_commitments where sales_order_line_id=line and planned_quantity=5) then raise exception 'SAMPLE_VENDOR_LOSS_DEMAND_WRONG';end if;
  begin perform public.production_command(c,'close_work_order',jsonb_build_object('work_order_id',wo,'revision',(select revision from public.work_orders where id=wo)),'vendor-close-before-qc');raise exception 'SAMPLE_VENDOR_FINAL_QC_CLOSURE_BYPASS';exception when others then if sqlerrm<>'QUALITY_PENDING' then raise;end if;end;
  perform public.quality_command(c,'inspect',jsonb_build_object('lot_id',vendor_return,'plan_id',final_plan,'kind','final','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8","8"]}]'::jsonb,'reason','SAMPLE processor check'),'vendor-inspect');
  perform public.release_stock_lot(c,vendor_return,1,'vendor-release');
  perform public.reserve_finished_goods(c,line,vendor_return,1,(select revision from public.sales_orders where id=so),'vendor-reserve');
  perform public.production_command(c,'create_work_order',jsonb_build_object('sales_order_line_id',line,'package_id',pkg,'number','SAMPLE-VENDOR-REPLACEMENT','quantity','5','start_date',current_date,'due_date',current_date+7),'vendor-replacement');
  raise exception 'SAMPLE_ROLLBACK_VENDOR_FIXTURE';
 exception when others then if sqlerrm<>'SAMPLE_ROLLBACK_VENDOR_FIXTURE' then raise;end if;end;
 -- A physical split does not waive the work order's final-QC closure gate.
 begin
  derived_lot:=public.transform_stock_lot(c,'split',jsonb_build_object('sources',jsonb_build_array(jsonb_build_object('lot_id',output_lot,'revision',2,'quantity','1')),'uom','pcs','location_id',loc,'lot_code','SAMPLE-CLOSE-GATE','reason','SAMPLE closure regression'),'closure-split');
  begin perform public.production_command(c,'close_work_order',jsonb_build_object('work_order_id',wo,'revision',(select revision from public.work_orders where id=wo)),'close-derived-held');raise exception 'SAMPLE_DERIVED_QC_CLOSURE_BYPASS';exception when others then if sqlerrm<>'QUALITY_PENDING' then raise;end if;end;
  raise exception 'SAMPLE_ROLLBACK_CLOSURE_FIXTURE';
 exception when others then if sqlerrm<>'SAMPLE_ROLLBACK_CLOSURE_FIXTURE' then raise;end if;end;
 select revision into revision_value from public.work_orders where id=wo;
 perform public.production_command(c,'close_work_order',jsonb_build_object('work_order_id',wo,'revision',revision_value),'close');
 if not exists(select 1 from public.production_demand_commitments where sales_order_line_id=line and planned_quantity=5) then raise exception 'SAMPLE_CLOSED_SCRAP_DID_NOT_FREE_DEMAND'; end if;
 j:=public.get_production_workspace(c);
 if not exists(select 1 from jsonb_array_elements(j->'demand') d where d->>'id'=line::text and (d->>'remaining_to_plan')::numeric=5) then raise exception 'SAMPLE_REPLACEMENT_DEMAND_HIDDEN'; end if;
 replacement_wo:=public.production_command(c,'create_work_order',jsonb_build_object('sales_order_line_id',line,'package_id',pkg,'number','SAMPLE-REPLACE','quantity','1','start_date',current_date,'due_date',current_date+7),'replace-work');
 if not exists(select 1 from public.production_demand_commitments where sales_order_line_id=line and planned_quantity=6) then raise exception 'SAMPLE_EXACT_REPLACEMENT_CAPACITY_WRONG'; end if;
 -- A zero-input successor cannot consume the last recovery path before materials are accounted.
 zero_wo:=public.production_command(c,'create_work_order',jsonb_build_object('sales_order_line_id',line,'package_id',pkg,'number','SAMPLE-ZERO','quantity','1','start_date',current_date,'due_date',current_date+7),'zero-work');
 perform public.production_command(c,'release_work_order',jsonb_build_object('work_order_id',zero_wo,'revision',1),'zero-release');
 select id into zero_job1 from public.job_cards where work_order_id=zero_wo and sequence=10;
 select id into zero_job2 from public.job_cards where work_order_id=zero_wo and sequence=20;
 perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',zero_job1,'revision',1),'zero-start1');
 perform public.production_command(c,'complete_job',jsonb_build_object('job_card_id',zero_job1,'revision',2,'good_quantity','0','scrap_quantity','1','reason','SAMPLE all scrap'),'zero-finish1');
 begin perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',zero_job2,'revision',1),'zero-before-consume'); raise exception 'SAMPLE_ZERO_SUCCESSOR_LOST_MATERIAL_RECOVERY'; exception when others then if sqlerrm<>'MATERIAL_UNACCOUNTED' then raise; end if; end;
 zero_issue:=public.production_command(c,'issue_material',jsonb_build_object('work_order_id',zero_wo,'job_card_id',zero_job2,'lot_id',lot,'quantity','0.1','uom','kg','lot_revision',(select revision from public.stock_lots where id=lot)),'zero-issue');
 perform public.production_command(c,'consume_material',jsonb_build_object('issue_id',zero_issue,'quantity','0.1','reason','SAMPLE scrap consumed'),'zero-consume');
 perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',zero_job2,'revision',1),'zero-start2');
 if not exists(select 1 from public.job_cards where id=zero_job2 and status='completed' and planned_quantity=0 and good_quantity=0 and scrap_quantity=0) then raise exception 'SAMPLE_ZERO_SUCCESSOR_FABRICATED_QUANTITY'; end if;
 perform public.production_command(c,'close_work_order',jsonb_build_object('work_order_id',zero_wo,'revision',(select revision from public.work_orders where id=zero_wo)),'zero-close');
 reservation:=public.reserve_finished_goods(c,line,output_lot,5,(select revision from public.sales_orders where id=so),'reserve');
 shipment:=public.prepare_packing_shipment(c,so,'SAMPLE-PACK','SAMPLE-SHIP',jsonb_build_array(jsonb_build_object('reservation_id',reservation,'quantity',5)),(select revision from public.sales_orders where id=so),'pack');
 ncr:=public.quality_command(c,'create_ncr',jsonb_build_object('lot_id',output_lot,'revision',(select revision from public.stock_lots where id=output_lot),'quantity','5','reason','SAMPLE contain after packing'),'ncr');
 begin perform public.dispatch_shipment(c,shipment,1,'blocked-ship'); raise exception 'SAMPLE_NCR_SHIPPING_BYPASS'; exception when others then if sqlerrm<>'LOT_QC_HOLD' then raise; end if; end;
 begin perform public.release_stock_reservation(c,reservation,'SAMPLE NCR recovery',(select revision from public.sales_orders where id=so),'unreserve-packed'); raise exception 'SAMPLE_PACKED_RESERVATION_RELEASED'; exception when others then if sqlerrm<>'PACKING_PENDING' then raise; end if; end;
 begin perform public.cancel_prepared_shipment(c,shipment,null,'SAMPLE missing revision','cancel-no-revision'); raise exception 'SAMPLE_CANCEL_NULL_REVISION_ALLOWED'; exception when others then if sqlerrm<>'REVISION_CONFLICT' then raise; end if;end;
 perform public.cancel_prepared_shipment(c,shipment,1,'SAMPLE NCR containment','cancel');
 if public.cancel_prepared_shipment(c,shipment,1,'SAMPLE NCR containment','cancel')<>shipment then raise exception 'SAMPLE_CANCEL_NOT_IDEMPOTENT'; end if;
 if not exists(select 1 from public.shipments where id=shipment and status='cancelled') or not exists(select 1 from public.stock_reservations where id=reservation and status='active' and consumed_quantity=0) or not exists(select 1 from public.stock_positions where lot_id=output_lot and on_hand=5 and reserved=5) then raise exception 'SAMPLE_CANCEL_REWROTE_STOCK'; end if;
 revision_value:=(select revision from public.sales_orders where id=so);
 begin perform public.release_stock_reservation(c,reservation,'SAMPLE missing revision',null,'release-no-revision-'||reservation::text); raise exception 'SAMPLE_UNRESERVE_NULL_REVISION_ALLOWED'; exception when others then if sqlerrm<>'REVISION_CONFLICT' then raise; end if;end;
 perform public.release_stock_reservation(c,reservation,'SAMPLE NCR recovery',revision_value,'unreserve');
 if public.release_stock_reservation(c,reservation,'SAMPLE NCR recovery',revision_value,'unreserve')<>reservation then raise exception 'SAMPLE_UNRESERVE_NOT_IDEMPOTENT'; end if;
 if not exists(select 1 from public.stock_reservations where id=reservation and status='released' and released_at is not null and consumed_quantity=0) then raise exception 'SAMPLE_UNRESERVE_LOST_HISTORY'; end if;
 payload:=jsonb_build_object('item_id',out_item,'revision_label','REWORK','basis_quantity','1','components',jsonb_build_array(jsonb_build_object('item_id',out_item,'quantity','1','uom','pcs','scrap_allowance_pct','0')),'operations',jsonb_build_array(jsonb_build_object('sequence',10,'work_centre_id',centre,'name','SAMPLE Rework')));
 rework_pkg:=public.production_command(c,'create_package',payload,'rework-package');
 perform public.production_command(c,'approve_package',jsonb_build_object('package_id',rework_pkg),'approve-rework-package');
 perform public.quality_command(c,'resolve_ncr',jsonb_build_object('ncr_id',ncr,'revision',1,'disposition','rework','package_id',rework_pkg,'number','SAMPLE-REWORK','start_date',current_date,'due_date',current_date+7,'reason','SAMPLE approved rework'),'resolve-rework');
 select id into rework_wo from public.work_orders where source_ncr_id=ncr;
 perform public.production_command(c,'release_work_order',jsonb_build_object('work_order_id',rework_wo,'revision',1),'release-rework');
 select id into rework_job from public.job_cards where work_order_id=rework_wo;
 rework_issue:=public.production_command(c,'issue_material',jsonb_build_object('work_order_id',rework_wo,'job_card_id',rework_job,'lot_id',output_lot,'quantity','5','uom','pcs','lot_revision',(select revision from public.stock_lots where id=output_lot)),'issue-rework');
 perform public.production_command(c,'consume_material',jsonb_build_object('issue_id',rework_issue,'quantity','5','reason','SAMPLE rework consumed'),'consume-rework');
 perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',rework_job,'revision',1),'start-rework');
 perform public.production_command(c,'complete_job',jsonb_build_object('job_card_id',rework_job,'revision',2,'good_quantity','4','scrap_quantity','1','reason','SAMPLE rework loss'),'finish-rework');
 rework_output:=public.production_command(c,'record_output',jsonb_build_object('work_order_id',rework_wo,'location_id',loc,'lot_code','SAMPLE-REWORK-OUTPUT','quantity','4','uom','pcs'),'rework-output');
 select lot_id into rework_lot from public.production_outputs where id=rework_output;
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',final_plan,'lot_id',rework_lot,'kind','final','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8","8"]}]'::jsonb,'reason','SAMPLE rework inspected'),'inspect-rework');
 perform public.release_stock_lot(c,rework_lot,1,'release-rework-lot');
 perform public.production_command(c,'close_work_order',jsonb_build_object('work_order_id',rework_wo,'revision',(select revision from public.work_orders where id=rework_wo)),'close-rework');
 if not exists(select 1 from public.ncrs where id=ncr and status='resolved' and disposition='rework') or not exists(select 1 from public.lot_genealogy where parent_lot_id=output_lot and child_lot_id=rework_lot and work_order_id=rework_wo) then raise exception 'SAMPLE_REWORK_HISTORY_MISSING'; end if;
 if not exists(select 1 from public.production_demand_commitments where sales_order_line_id=line and planned_quantity=5) then raise exception 'SAMPLE_REWORK_SCRAP_REPLACEMENT_WRONG'; end if;
 reservation:=public.reserve_finished_goods(c,line,rework_lot,4,(select revision from public.sales_orders where id=so),'reserve-reworked');
 shipment:=public.prepare_packing_shipment(c,so,'SAMPLE-PACK-REWORK','SAMPLE-SHIP-REWORK',jsonb_build_array(jsonb_build_object('reservation_id',reservation,'quantity',2)),(select revision from public.sales_orders where id=so),'pack-reworked');
 perform public.dispatch_shipment(c,shipment,1,'ship-reworked');
 begin perform public.release_stock_reservation(c,reservation,'SAMPLE missing revision',null,'release-no-revision-'||reservation::text); raise exception 'SAMPLE_UNRESERVE_NULL_REVISION_ALLOWED'; exception when others then if sqlerrm<>'REVISION_CONFLICT' then raise; end if;end;
 perform public.release_stock_reservation(c,reservation,'SAMPLE remaining allocation change',(select revision from public.sales_orders where id=so),'unreserve-part-shipped');
 if not exists(select 1 from public.stock_reservations where id=reservation and status='released' and consumed_quantity=2 and released_at is not null) or not exists(select 1 from public.stock_positions where lot_id=rework_lot and on_hand=2 and reserved=0 and available_to_promise=2) then raise exception 'SAMPLE_UNRESERVE_CHANGED_DISPATCHED_QUANTITY'; end if;
 j:=public.get_production_workspace(c); if jsonb_array_length(j->'works')<>4 or jsonb_array_length(j->'jobs')<>5 then raise exception 'SAMPLE_PRODUCTION_READ_INVALID'; end if;
 j:=public.get_quality_workspace(c); if jsonb_array_length(j->'genealogy')<>3 then raise exception 'SAMPLE_QUALITY_READ_INVALID'; end if;
 -- Split and merge finished output must retain its production allocation and final-QC context.
 payload:=jsonb_build_object('sources',jsonb_build_array(jsonb_build_object('lot_id',rework_lot,'revision',(select revision from public.stock_lots where id=rework_lot),'quantity','1')),'uom','pcs','location_id',loc,'lot_code','SAMPLE-DERIVED','reason','SAMPLE production split');
 derived_lot:=public.transform_stock_lot(c,'split',payload,'split-produced');
 if not exists(select 1 from public.lot_trace_context where lot_id=derived_lot and requires_final and sales_order_line_id=line and work_order_ids=array[rework_wo]) then raise exception 'SAMPLE_PRODUCTION_CONTEXT_LOST';end if;
 begin perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',final_plan,'lot_id',derived_lot,'kind','incoming','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8","8"]}]'::jsonb,'reason','SAMPLE wrong context'),'wrong-derived-stage');raise exception 'SAMPLE_DERIVED_FINAL_QC_BYPASSED';exception when others then if sqlerrm<>'INSPECTION_CONTEXT_MISMATCH' then raise;end if;end;
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',final_plan,'lot_id',derived_lot,'kind','final','revision',1,'readings','[{"key":"dimension","uom":"mm","values":["8","8"]}]'::jsonb,'reason','SAMPLE derived check'),'inspect-derived');
 perform public.release_stock_lot(c,derived_lot,1,'release-derived');
 derived_reservation:=public.reserve_finished_goods(c,line,derived_lot,1,(select revision from public.sales_orders where id=so),'reserve-derived');
 if not exists(select 1 from public.stock_positions where lot_id=derived_lot and reserved=1) then raise exception 'SAMPLE_DERIVED_RESERVATION_WRONG';end if;
 payload:=jsonb_set(payload,'{sources,0,lot_id}',to_jsonb(derived_lot));payload:=jsonb_set(payload,'{sources,0,revision}',to_jsonb((select revision from public.stock_lots where id=derived_lot)));payload:=jsonb_set(payload,'{lot_code}','"SAMPLE-RESERVED-SPLIT"');
 begin perform public.transform_stock_lot(c,'split',payload,'reserved-split');raise exception 'SAMPLE_RESERVED_SPLIT_ALLOWED';exception when others then if sqlerrm<>'INSUFFICIENT_AVAILABLE_STOCK' then raise;end if;end;
 perform public.release_stock_reservation(c,derived_reservation,'SAMPLE consolidation',(select revision from public.sales_orders where id=so),'release-derived-reservation');
 payload:=jsonb_build_object('sources',jsonb_build_array(jsonb_build_object('lot_id',derived_lot,'revision',(select revision from public.stock_lots where id=derived_lot),'quantity','1'),jsonb_build_object('lot_id',external_lot,'revision',(select revision from public.stock_lots where id=external_lot),'quantity','1')),'uom','pcs','location_id',loc,'lot_code','SAMPLE-MIXED','reason','SAMPLE mismatch');
 begin perform public.transform_stock_lot(c,'merge',payload,'mixed-origin');raise exception 'SAMPLE_ALLOCATION_MIX_ALLOWED';exception when others then if sqlerrm<>'LOT_CONTEXT_MISMATCH' then raise;end if;end;
 payload:=jsonb_set(payload,'{sources,1,lot_id}',to_jsonb(rework_lot));payload:=jsonb_set(payload,'{sources,1,revision}',to_jsonb((select revision from public.stock_lots where id=rework_lot)));payload:=jsonb_set(payload,'{lot_code}','"SAMPLE-MERGED-OUTPUT"');
 merged_lot:=public.transform_stock_lot(c,'merge',payload,'merge-produced');
 if not exists(select 1 from public.lot_trace_context where lot_id=merged_lot and requires_final and sales_order_line_id=line and cardinality(work_order_ids)=1) then raise exception 'SAMPLE_MERGED_CONTEXT_LOST';end if;
 derived_ncr:=public.quality_command(c,'create_ncr',jsonb_build_object('lot_id',merged_lot,'revision',1,'quantity','1','reason','SAMPLE partial reject'),'derived-ncr');
 perform public.quality_command(c,'resolve_ncr',jsonb_build_object('ncr_id',derived_ncr,'revision',1,'disposition','scrap','reason','SAMPLE derived scrap'),'derived-scrap');
 if not exists(select 1 from public.production_demand_commitments where sales_order_line_id=line and planned_quantity=4) then raise exception 'SAMPLE_DERIVED_SCRAP_DEMAND_WRONG';end if;
 derived_ncr:=public.quality_command(c,'create_ncr',jsonb_build_object('lot_id',merged_lot,'revision',(select revision from public.stock_lots where id=merged_lot),'quantity','1','reason','SAMPLE derived rework'),'derived-rework-ncr');
 perform public.quality_command(c,'resolve_ncr',jsonb_build_object('ncr_id',derived_ncr,'revision',1,'disposition','rework','package_id',rework_pkg,'number','SAMPLE-DERIVED-REWORK','start_date',current_date,'due_date',current_date+7,'reason','SAMPLE retained allocation'),'derived-rework');
 if not exists(select 1 from public.work_orders where source_ncr_id=derived_ncr and sales_order_line_id=line and parent_work_order_id=rework_wo and bom_revision_id=(select bom_revision_id from public.engineering_packages where id=rework_pkg)) then raise exception 'SAMPLE_DERIVED_REWORK_PINS_LOST';end if;
 perform set_config('request.jwt.claim.sub',current_setting('app.sample_outsider_id'),true);
 if jsonb_array_length(public.get_production_workspace(c)->'works')<>0 or jsonb_array_length(public.get_quality_workspace(c)->'plans')<>0 then raise exception 'SAMPLE_FACTORY_TENANT_LEAK'; end if;
 begin perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job1,'revision',4),'outsider'); raise exception 'SAMPLE_FACTORY_COMMAND_LEAK'; exception when others then if sqlerrm<>'FORBIDDEN' then raise; end if; end;
end $$;
